    std::vector<unsigned> edge_vertices;
    std::vector<RT::Vertex_handle> vertices;
    for (int i = 0; i < 4; ++i) {
        if (i != k) vertices.push_back(c->vertex(i));
    }
    for (int i = 0; i < 3; ++i) {
        for (int j = i + 1; j < 3; ++j) {
            RT::Vertex_handle v1 = vertices[i];
            RT::Vertex_handle v2 = vertices[j];
            if (rt.is_infinite(v1) || rt.is_infinite(v2)) continue;
            Point p1 = rt.dual(v1);
            Point p2 = rt.dual(v2);
            edge_vertices.push_back(result.vertices.size());
            result.vertices.push_back(p1);
            edge_vertices.push_back(result.vertices.size());
            result.vertices.push_back(p2);
        }
    }
    if (!edge_vertices.empty()) {
        double area = 0.0;
        for (int i = 0; i < 3; ++i) {
            for (int j = i + 1; j < 3; ++j) {
                RT::Vertex_handle v1 = vertices[i];
                RT::Vertex_handle v2 = vertices[j];
                RT::Vertex_handle v3 = vertices[3 - i - j];
                if (rt.is_infinite(v1) || rt.is_infinite(v2) || rt.is_infinite(v3)) continue;
                Point p1 = rt.dual(v1);
                Point p2 = rt.dual(v2);
                Point p3 = rt.dual(v3);
                Vector v12 = p2 - p1;
                Vector v13 = p3 - p1;
                Vector cross = CGAL::cross_product(v12, v13);
                area += cross.squared_length();
            }
        }
        area = std::sqrt(area) / 2.0;
        result.push_back(edge_vertices, area);
    }
}
return result;

